import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷三十五","description":"周易經傳集解 - 周易經傳集解卷三十五","frontmatter":{"title":"周易經傳集解卷三十五","description":"周易經傳集解 - 周易經傳集解卷三十五"},"headers":[],"relativePath":"classics/jingchuan-jijie/036.md","filePath":"classics/jingchuan-jijie/036.md"}'),r={name:"classics/jingchuan-jijie/036.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷三十五",tabindex:"-1"},[n("周易經傳集解卷三十五 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷三十五","aria-label":"Permalink to “周易經傳集解卷三十五”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷三十五 ​宋林栗撰。文言 ​昔者聖人之作易也，幽贊於神明而生蓍，參天兩地而倚數，觀變於陰陽而立卦，發揮於剛柔而生爻，和順於道德而理於義，窮理盡性以至於命。繫辭言：「包犧氏仰觀俯察，近取諸身，遠取諸物，於是始作八卦。」其取之也固已不一而足。於此又言「聖人作易，幽贊於神明而生蓍，參天兩地而倚數，觀變於陰陽而立卦，發揮於剛柔而生爻」者，其文王、周公之謂乎？子曰：「天生神物，聖人則之。」又曰：「是興神物，以前民用。」然則幽隱之中，神明贊之，是生神物，以開聖治。古先所傳，不可誣也。近世儒者或不取禎祥之論，遂以生蓍與倚數立卦生爻同義，不知生蓍之與倚數，何以別而為二乎？所謂「天生神物，聖人則之」者，又將何謂也？夫蓍一本而百莖，蓋得大衍之數二焉。聖人用其半，參取於天，兩取於地，而依五十之蓍以定大衍之數，是之謂倚數也。參取於天，一三五也。兩取於地，二與四也。一三五合而為九，二與四合而為六。參兩者，五也。九六者，十五也。十而五之者，五十也。是參天兩地之積也。或曰：蓍百莖而用其半，何也？曰：聖人中天地而立人極，故天地之數，取其五以為宗；八卦之數，取其四以為揲；四象之數，取其二以為變。用蓍之半，不亦宜乎？五十之蓍，兩儀四象，其陰陽之變無窮，得九六者為乾坤，得七八者為六子。四象列而八卦成，八卦成而六十四象於是乎立卦。卦立矣，然後發揮六畫於剛柔之位，於是乎生爻。陰陽者，言其氣也。剛柔者，言其體也。由蓍而倚數，由數而立卦，由卦而生爻，凡此皆本於道德而出之者也。故曰：「和順於道德而理於義。」道者，尊也，德之原也；德者，得也，道之繼也；義者，宜也，德之發也。由道而後德，由德而後義，順流而下者也，故曰「和」，曰「順」，曰「理」。道寓乎數，和之則無乖。德成乎卦，順之則不逆。義陳乎爻，理之則不亂。陰陽之謂道，仁義之謂德，剛柔之謂義。義也者，理也；德也者，性也；道也者，命也。學者必將反而求之，溯流以達其源，故曰：「窮理盡性以至於命。」由理而後性，由性而後命，此則溯流而上者也，故曰「窮」，曰「盡」，曰「至」。理在於物，必先窮之，然後可以言性。性存乎己，必先盡之，然後可以言命。命受於天，非人力之所為，至焉而已矣。至之為言極矣，不可以有加矣。中庸曰：自誠明謂之性，自明誠，謂之教。自明而誠者，和順於道德，而理於義也。自誠而明者，窮理盡性，以至於命也。元者，善之長也；亨者，嘉之會也；利者，義之和也；貞者，事之幹也。君子體仁足以長人；嘉會足以合禮，利物足以和義，貞固足以幹事。君子行此四德者，故曰：「乾，元亨利貞。」初九曰，「潛龍勿用」，何謂也？子曰：「龍德而隱者也。不易乎世，不成乎名，遁世無悶，不見是而無悶。樂則行之，憂則違之，確乎其不可扷潛龍也。」九二曰，「見龍在田，利見大人」，何謂也？子曰：「龍德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化。易曰：見龍在田，利見大人。君德也。」九三曰，「君子終日乾乾，夕惕若，厲無咎」，何謂也？子曰：「君子進德修業，忠信，所以進德也；修辭立其誠，所以居業也。知至至之，可與幾也；知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。」九四曰，「或躍在淵，無咎」，何謂也？子曰：「上下無常，非為邪也；進退無恆，非離群也。君子進德修業，欲及時也，故無咎。」九五曰，「飛龍在天，利見大人」。何謂也？子曰：「同聲相應，同氣相求。水流溼，火就燥，雲從龍，風從虎。聖人作而萬物睹。木乎天者親上，本乎地者親下，則各從其類也。」上九曰，「亢龍有悔」。何謂也？子曰：「貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。」「潛龍勿用」，下也。「見龍在田」，時舍也。「終日乾乾」，行事也。「或躍在淵」，自試也。「飛龍在天」，上治也。「亢龍有悔」，窮之災也。乾元「用九」，天下治也。「潛龍勿用」，陽氣潛藏。「見龍在田」，天下文明。「終日乾乾」，與時偕行。「或躍在淵」，乾道乃革。「飛龍在天」，乃位乎天德。「亢龍有悔」，與時偕極。乾元「用九」，乃見天則。乾「元」者，始而亨者也。「利貞」者，性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎！剛健中正，純粹精也。六爻發揮，旁通情也。時乘六龍，以「御天」也。雲行雨施，天下平也。君子以成德為行，日可見之行也。潛之為言也，隱而未見，行而未成，是以君子弗用也。君子學以聚之，問以辨之，寬以居之，仁以行之。易曰：「見龍在田，利見大人」，君德也。九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危無咎矣。九四重剛而不中正，上不在天，下不在田，中不在人，故「或」之。或之者，疑之也，故無咎。夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶。先天而天弗違，後天而奉天時。天且弗違，而況於人乎？況於鬼神乎？「亢」之為言也，知進而不知退，知存而不知亡，知得而不知喪。其唯聖人乎？知進退存亡而不失其正者，其唯聖人乎？「坤」至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行。積善之家，必有餘慶，積不善之家，必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辨之不早辯也。易曰「履霜堅冰至」，蓋言順也。「直」其正也，方其義也，君子敬以直內，義以方外，敬義立而德不孤。「直方大，不習無不利」，則不疑其所行也。陰雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也，地道無成，而代有終也。天地變化，草木蕃；天道閉，賢人隱。易曰「括囊，無咎無譽」，蓋言謹也。君子黃中通理，正位居體，美在其中，而暢於四肢，發於事業，美之至也。陰疑於陽必戰，為其嫌於無陽也，故稱龍焉；猶未離其類也，故稱血焉。夫玄黃者，天地之雜也，天玄而地黃。昔者聖人之作易也，將以順性命之理。是以立天之道，曰陰與陽；立地之道，曰柔與剛；立人之道，曰仁與義。兼三才而兩之，故易六畫而成卦；分陰分陽，迭用柔剛，故易六位而成章。數往者順，知來者逆，是故易逆數也。此章申言性命之理，前以逆數之，此復順言之，前以序陳之，此復錯揉之，其義則一而已。理亦性也，性亦命也。命在乎天，理在乎地，性存乎人。是以「立天之道，曰陰與陽」者，上二畫也；「立地之道，曰柔與剛」者，下二畫也；「立人之道，曰仁與義」者，中二畫也。此之謂順也。兼三才而兩之，故陰、陽、仁、義、剛、柔，六畫而成卦。分陰陽之畫，而迭用於剛柔之位，故初、二、三、四、五上，六位而成章。畫自上而下，故曰「數往者順」。位自下而上，故曰「知來者逆」。和順於道德而理於義者，「數往」之謂也。「窮理盡性以至於命」者，「知來」之謂也。卦既立矣，爻既陳矣，則初上者，本末之地，始終之序，故曰「易逆數也」。數，讀如數往之數，由下而數之至於上也。陰陽，氣也。柔剛，體也。畫以氣言，「在天成象」也。位以體言，「在地成形」也。畫順而下，陽之降也。位溯而上，陰之升也。夫易之為書，陰陽剛柔而已。世之儒者，知天之為陽，地之為陰，乾之為剛，坤之為柔，而不知天之道固備乎陰陽，地之道固全乎柔剛也。知天道曰陰陽，地道曰柔剛，而不知天之道亦兼乎柔剛，地之道亦足乎陰陽也。近取諸人，男屬乎陽，女屬乎陰；男稟乎剛，女稟乎柔。然一人之身，有不備乎陰陽剛柔者哉？五藏六腑，四肢百體，各有陰陽剛柔之配。然一體之中，有不備乎陰陽剛柔者哉？此易之所以分陰分陽，而迭用柔剛之義也。愚謂：「天地定位」而下，方是說卦之文。自「昔者聖人」二段至「易逆數也」，當合文言為一篇。蓋先儒既取文言分系於乾坤，而其首末附入於此。自「六位而成」章下文又脫「數往者順」以下十四字。然去聖久遠，無所質疑，姑志於此，以俟來哲。說卦 ​天地定位，山澤通氣，雷風相薄，水火不相射。八卦相錯。雷以動之，風以散之，雨以潤之，日以烜之，艮以止之，兌以說之，乾以君之，坤以藏之。天高以覆地，地下以承天，是謂定位。山氣流於澤，澤氣蒸于山，是謂通氣。雷遇風而震，風遇雷而怒，是謂相薄。水入火而焦，火入水而滅，是謂不相射。此八物也，而八卦象之，故相錯而成六十四也。天地之間，一物之生，非是八者不能以成。雷以動之而後生，風以散之而後拆，雨以潤之而後滋，日以烜之而後暢，艮以止之而後成，兌以說之而後遂，乾以君之而得其所覆，坤以藏之而得其所歸。然雷風雨日則言其物，艮兌乾坤則稱其名，何也？王肅雲：「互相備也。」愚謂動、入、陷、麗，非全美之名，而雷風雨日，有不測之用，名不足，故言其物也。天地山澤，乃一定之體，而健順止說，有成物之功，物不足，故稱其名也。前言「天地」而後及「六子」，後言「六子」而終於乾「坤」者，明八卦之循環也。自此以下，或雜乾「坤」於「六子」之中，或遺「乾」、坤於六子之外，皆相錯義也。帝出乎震，齊乎巽，相見乎離，致役乎坤，說言乎兌，戰乎乾，勞乎坎，成言乎艮。萬物出乎震，震，東方也。齊乎巽，巽，東南也。齊也者，言萬物之潔齊也。離也者，明也，萬物皆相見，南方之卦也。聖人南面而聽天下，嚮明而治，蓋取諸此也。坤也者，地也，萬物皆致養焉，故曰「致役乎坤」。兌，正秋也，萬物之所說也，故曰「說言乎兌」。戰乎乾，乾，西北之卦也，言陰陽相薄也。坎者，水也，正北方之卦也，勞卦也，萬物之所歸也，故曰「勞乎坎」。艮，東北之卦也，萬物之所成終而所成始也，故曰「成言乎艮」。神也者，妙萬物而為言者也。動萬物者，莫疾乎雷。撓萬物者，莫疾乎風。燥萬物者，莫熯乎火。說萬物者，莫說乎澤。潤萬物者，莫潤乎水。終萬物始萬物者，莫盛乎艮。故水火相逮，雷風不相悖，山澤通氣，然後能變化，既成萬物也。帝者，萬物之宰也。帝出乎震，則萬物不得不出；萬物成乎艮，則帝之功亦成矣。出而潔齊而相見，見而致養，養而後說，說而後戰，戰而後勞，勞而後成，成而後出，自然之序也。聖人為其語簡，復從而釋之。「震」，東方也，於時而春，於日為旦，物動而出也。巽，東南也，春夏之交，辰巳之間，潔齊而未用也。離，南方也，於時為夏，於日為中，嚮明而利見。坤，西南也，夏秋之交，未申之間，致役而遂養也。兌，西方也，於時為秋，於日為晡，物息而相說也。乾，西北也，秋冬之交，戌亥之間，陰盛而疑，陽相薄而戰也。坎，北方也，於時為冬，於日為中，物息而相勞也。艮，東北也，冬春之交，醜寅之間，歸者成終，而出者成始也。聖人之言，蓋有所互明焉。故曰：「離也者，明也。」則坎之為幽，震之為旦，兌之為暮可知矣。坤也者，地也。則乾之為天，艮之為山，兌之為澤，可知矣。坎者，水也。則離之為火，震、巽之為木，乾、兌之為金，坤、艮之為土，可知矣。坎，勞卦也，則離之為暇，震之為作，兌之為息，可知矣。聖人嚮明而治，蓋取諸此也。則昧爽丕顯，嚮晦入息，從可知矣。「聽天下」雲者，達四聰之義也。彼豐其屋，蔀其家者，所聽止於近習而已。震、離、坎言「方」，而乾、艮、巽不言者，四維也。坤、兌不及「方」者，言物之養莫如地，言物之說莫如秋也。離、坎言「方」而兼其時物者，南與明皆物之所觀，北與水皆物之所歸也。蘇氏曰：「二言，衍文也。」古者說、兌通，或無言者，或從言者，訛而加之耳。當曰說乎兌，誠乎艮。誠者，物之終始，不誠無物，故曰「誠乎艮也。或曰：八卦之配於五行，坎水、離火、兌金、震木，四時之物，各位其方者也。乾金西北，巽木東南，何也？」曰：「水火生而可用也，金木成而後可用也。故巽位於東南，乾位於西北，皆其成也。」八卦之物，乾為金，巽為木，而不言於震兌者，以其未成也。坤位西南，艮位東北，而俱為土，何也？曰：四時之季，土用其事。其在東南也，畏於木，其在西北也，遜於金，故其用不足言也。其在東北也，火以七為之生；其在西南也，水以六為之用，故致養於坤，而始終乎艮也。八卦之說，坤為地，艮為山，而俱不言土者，以其共之也。坎為勞卦，何也？曰：夫物勞於用而不勞於生，勞於逆而不勞於順。故木之生火，火之生土，土之生金，金之生水，出於自然，未嘗勞也。水之生木，則有灌溉之勞矣。自春而夏，自夏而秋，自秋而冬，順而行之，未嘗勞也；自冬而春，則有朔易之勞矣。故曰坎者，水也，正北方之卦也。勞，勞也，萬物之所歸也。因其勞而勞之，故曰勞乎坎。在卦之井，木上有水，君子以勞民勸相，蓋取諸此也。傳曰：一則神，兩則化。子曰：「知變化之道者，其知神之所為乎？」是故妙物者，謂之神。動之、撓之、燥之、說之、潤之、成之者，謂之變化。化則神矣，神則化矣。水火相逮而不相射，雷風相薄而不相悖，山高澤下而其氣相通，是之謂神，所以能變化也。或曰：「山澤通氣，而終萬物，始萬物，獨不言山，何也？」曰：終始萬物，山不足以充其義也。「坎離不言雨日，而言水火，何也？」曰：雨日之功，不可同時，水火則相逮而濟者也。故震巽有在天之象，而無在地之形；艮兌有在地之形，而無在天之象。唯坎離居中，在天則為雨日，在地則為水火。故言其用則取諸天，言其象則取諸地也。知此者，可與言象矣。乾，健也。坤，順也。震，動也。巽，入也。坎，陷也。離，麗也。艮，止也。兌，說也。乾為馬，坤為牛，震為龍，巽為雞，坎為豕，離為雉，艮為狗，兌為羊。乾為首，坤為腹，震為足，巽為股，坎為耳，離為目，艮為手，兌為口。至剛不得不健，至柔不得不順。健，在下不得不動，在中不得不陷，在上不得不止。順，在下不得不入，在中不得不麗，在上不得不說。此天地萬物自然之理也，而八卦象之。故在下有動入之象，在中有陷麗之象，在上有止說之象。動近乎健，入近乎順者，乾坤之一變也。健順無作，動入有為，此其所以異也。及其究也，則動反為止，入反為說。其未止也，陷於陰；其未說也，麗於陽，皆自然之理也。健故為順，故為地。動故「為雷」，雷入故「為風」。陷故「為水」。麗故「為火」，止故「為山」，說故「為澤」。健故「為馬」，順故「為牛」。動故「為龍」，入故「為雞」。陷故「為豕」。麗故「為雉」。止故「為狗」，說故「為羊」。是謂「遠取諸物」也。首象其尊，腹象其虛，足象其動，股象其隨，耳象其通，目象其明，手象其止，口象其說，是謂「近取諸身」也。或曰：「動為龍，入為雞，何義也？」曰：「龍，動而升騰者也。雞，入而伏藏者也。」「陷為豕，麗為雉，何也？」曰：「豕，汙穢而陷泥塗者也；雉，文明而麗草木者也。」「止為狗，說為羊，何也？」曰：「狗遇物而止者也，羊見尊而說者也。」「手象其止，何也？」曰：「手動而有所止者也，若足之動，則無所不至矣。艮亦陽物也，豈其不動而已乎？故止與靜，文似而義殊矣。」「口象其說，何也？」曰：口，易說者也，說而見於外也。人之說也，宣之於口，故喜亦從口。喜說之「說」，通乎言說之「說」，皆兌象也。乾，天也，故稱乎父。坤，地也，故稱乎母。震一索而得男，故謂之長男。巽一索而得女，故謂之長女。坎再索而得男，故謂之中男。離再索而得女，故謂之中女。艮三索而得男，故謂之少男。兌三索而得女，故謂之少女。子曰：「探頤索隱，鉤深致遠，莫大乎蓍龜。」索，搜求也。揲蓍之策，四營而成易，三變而成爻，所以搜索乎幽深者也。乾三索皆陽也，坤三索皆陰也。故乾為天而稱父，坤為地而稱母。書曰「唯天地萬物父母」，以其得陰陽之純粹而不雜故也。乾道成男，坤道成女。故一索而得陽，其卦成震，則謂之長男；再索而得陽，其卦成坎，則謂之中男；三索而得陽，其卦成艮，則謂之少男；一索而得陰，其卦成巽，則謂之長女；再索而得陰，其卦成離，則謂之中女；三索而得陰，其卦成兌，則謂之少女。男女之辨以剛柔，長少之差以先後也。乾為天，為圜，為君，為父，為玉，為金，為寒，為冰，為大赤，為良馬，為老馬，為瘠馬，為駁馬，為木果，為天，天行健也；為圜，圜則行也。為君、為父，尊嚴也；為玉、為金，堅剛也；為寒、為冰，西北之卦也，水得金氣而堅凝也。為大赤，純陽之色也。為良馬，健而有德也；為老馬，久而知險也。為瘠馬，多骨而能行也。為駁馬，強力而百獸之所畏也。舊說駁馬食虎豹。為木果實也，陽種也。秋冬之交，木果成矣。坤為地，為母，為布，為釜，為吝嗇，為均，為子母牛，為大輿，為文，為眾，為柄。其於地也為黑。「為地」，承天而順也；「為母」，配父而資生也。「為布」者，布帛之布，經緯而成也。「為釜」者，釜鍾之釜，寬虛而容也。「為吝嗇」，陰性也；「為均」，純德也；「為子母牛」，母生而子順也；「為大輿」，上任而下行也；「為文」，西南之卦，赤白成文也；「為眾」，自二至十倍於乾；「為柄」，居物之後也；「為黑」，正陰之色也。震為雷，為龍，為玄黃，為敷，為大塗，為長子，為決躁，為蒼筤竹，為萑葦。其於馬也，為善鳴，為馵足，為作足，為的顙。其於稼也。為反生，其究為健，為蕃鮮。「為雷」，陽之動也；「為龍」，陽之升也；「為玄黃」，天地之始交也；「為敷」，草木之始華也；「為大塗」，萬物出而共由也；「為長子」，一索而得男也；「為決躁」，一陽在二陽之下，其情躁怒，必決而後已也；「為蒼筤竹」，東方之色也；「為萑葦」，草木之易生者也。「其於馬也，為善鳴」，陽不得其平，動而有聲也；「為作足」，方動之初，自力於行也；「為馵足」，陰在二，其色見於足也。「為的顙」，陰在上，其色見於顙也。「其於稼也，為反生」，既獲而更生者也。上二陰為槁桔，下一陽為根苖。「究」之言極也。極其動為「健」，極其敷為「蕃鮮」。健者，「乾」之德；蕃鮮者，「巽」之時也。一陽之究，則為三陽之「乾」；其究而變，則為一陰之「巽」也。或曰：乾之金玉，其為堅剛則同然金變而玉不變，玉毀而金不毀。震之竹葦，其為青青則同然竹堅而葦脆，葦枯而竹不衰。其同稱之，何也？曰：言各有當也。玉以象其自然之粹，金以言其百鍊之精，竹以象其勁直不御之𫝑，葦以象其決躁易衰之情也。或曰：「震，東方木也；巽，東南木之餘氣也。今震為竹，而巽為木，何也？」曰：木以漸而長，至巽而後成竹，一枝而幹霄，是以系之震也。巽為木，為風，為長女，為繩直，為工，為白，為長，為高，為進退，為不果，為臭。其於人也，為寡發，為廣顙，為多白眼，為近利市三倍。其究為躁卦。「為木」，巽而升也。「為風」，巽而入也。「為長女」，一索而得女也。「為繩直」，執柔以齊物也。「為工」，隨物以為制也。「為白」，少陰之色也。一陽為蒼，三陽為「大赤」。一陰為白，三陰為大黑也。「為長」、「為高」，以漸而致之也。風以況其長，木以況其高也。「為進退」、「為不果」，陰性慾下，而二陽俱升也。為臭，隨風而還，無所不入也。震為聲，巽為臭。乾坤之載，則無聲無臭矣。「為寡發」，陰少而不榮也。「為廣顙」，陽多而外見也。「為多白眼」，陽多而陰伏也。「為近利市三倍」，外實內虛，則貨財入也。「其究為躁卦」，亦以其變言之也。八卦唯震巽言其究者，原始反終也。其餘可以類求矣。坎為水，為溝瀆，為隱伏，為矯輮，為弓輪。其於人也，為加憂，為心病，為耳痛，為血卦，為赤。其於馬也，為美脊，為亟心，為下首，為薄蹄，為曳。其於輿也，為多眚，為通，為月，為盜。其於木也，為堅多心，為水陷也。北方之氣，升而為雲，降而為雨，源而為泉，流而為川，導而為溝，決而為瀆，皆坎也。唯壅而為澤，則兌之象矣。「為隱伏」，陽陷於陰也。「為矯輮，為弓輪」，剛制於柔而不失乎中者也。「其於人也，為加憂，為心病」，水克火也。「為耳痛。為血卦」，陰盛而陷陽也。為赤。其於馬為美脊。為亟心，陽在中也。「為下首，為薄蹄，為曳」，陰在外也。「其於輿也，為多眚」，陰陷故也。「為通」，如水之流行也。「為月」，在晦而明，水之精也。「為盜」，晝伏而夜動，陽之寇也。「其於木也，為堅多心」，亦以剛中而柔外故也。艮外剛，故為「堅多節」。離中虛，故為「堅多心」也。離為火，為日，為電，為中女，為甲冑，為戈兵。其於人也，為大腹。為乾卦，為鱉，為蟹，為嬴，為蚌，為龜。其於木也，為科上槁。「為火」，南方之卦也。「為日」、「電」，火之精也。「為中女」，再索也。「為甲冑」、「為戈兵」，外剛而內柔，人之所以衛其身也。「其於人也，為大腹」，外實而中虛也。「為乾卦」，火炎上炎，日麗天也。「為鱉」、「為蟹」、「為嬴」、「為蚌」、「為龜」，皆外剛而內柔也。「其於木也，為科上槁」，亦以其堅而中枯故也。艮為山，為徑路，為小石，為門闕，為果蓏，為閽寺，為指，為狗，為鼠，為黔喙之屬。其於木也，為堅多節。「為山」，止也。「為徑路」，山之蹊小而高也。「為小石」，山之物小而堅也。「乾為玉」，玉，韞於石中者也。「艮為小石」，其乾之究乎？「為門闕」，上實而下虛，於此乎出入也。震為大塗，而艮為徑路，震為重門，而艮為門闕，皆相因之象也。「為果蓏」，草木實也。「乾為木果」，而艮亦稱之者，艮之陽即乾之陽也。以其在上而止，故系之艮；以其資始而不窮，故系之乾也。剝之上九，「碩果不食」，則取諸艮矣。「震為龍」，而乾之六爻皆稱龍者，震之龍亦乾之龍也。以其自下而升，故系之「震」；以其變化不測，故系之「乾」也。「為閽寺，為狗」，捍外而守內也。「為指」，手之窮也。「為鼠」，小而黠也。「為黔喙，為堅多心」，亦以其外剛故也。兌為澤，為少女，為巫，為口舌，為毀折，為附決。其於地也，為剛滷，為妾，為羊，為澤，說也。「為少女」，三索也。「為巫覡」，以說神為職也；「為口舌」，以說人為事也；「為毀折」，西方之氣，凋落之形也。「為附決」，陰在外，不敢敵剛，附從其決也。「其於地為剛滷」，下剛而上柔也；「為妾」，女之賤而容說者也；「為羊」，外柔中狠，見草而說者也。凡說卦之象，大率皆舉一隅，亦有舉其「二」「三」者。蓋聖人見天下之「賾」，而擬諸其形容。其物名象類多隱類，奧而難知，姑摭其近於人而可以遂意者，附著其下，將求明者而質之。序卦 ​有天地，然後有萬物生焉。盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以蒙，蒙者，蒙也，物之稚也。物稚不可不養也，故受之以需，需者，飲食之道也。飲食必有訟，故受之以「訟」。訟必有眾起，故受之以「師」。師者，眾也。眾必有所比，故受之以「比」。比者，比也。比必有所畜，故受之以「小畜」。物畜然後有禮，故受之以履。履而泰然後安，故受之以泰，泰者，通也。物不可終通，故受之以否。物不可以終否，故受之以同人。與人同者，物必歸焉，故受之以大有。有大者不可以盈，故受之以謙。有大而能謙必豫，故受之以豫。豫必有隨，故受之以隨。以喜隨人者必有事，故受之以蠱。蠱者，事也。有事而後可大，故受之以臨，臨者，大也。物大然後可觀，故受之以觀。可觀而後有所合，故受之以噬嗑，嗑者，合也。物不可以苟合而已，故受之以賁。賁，飾也也。致飾然後亨則盡矣，故受之以剝。剝者，剝也。物不可以終盡，剝窮上反下，故受之以復。復則不妄矣，故受之以無妄。有無妄然後可畜，故受之以大畜。物畜然後可養，故受之以頤。頤者，養也。不養則不可動，故受之以大過。物不可以終過，故受之以坎。坎者，陷也。陷必有所麗，故受之以離。離者，麗也。有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦，有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯。夫婦之道不可以不久也，故受之以恆。恆者，久也。物不可以久居其所，故受之以「遁」。「遁」者，退也。物不可以終遁，故受之以「大壯」。物不可以終壯，故受之以「晉」。「晉」者，進也。進必有所傷，故受之以「明夷」。「夷」者，傷也。傷於外者必反於家，故受之以「家人」。家道窮必乖，故受之以「暌」。「暌」者，乖也。乖必有難，故受之以「蹇」。「蹇」者，難也。物不可以終難，故受之以「解」。「解」者，緩也。緩必有所失，故受之以「損」。損而不已必益，故受之以「益」。益而不已必決，故受之以「夬」。「夬」者，決也。決必有所遇，故受之以「姤」。「姤」者，遇也。物相遇而後聚，故受之以「萃」。「萃」者，聚也。聚而上者謂之升，故受之以「升」。升而不已必困，故受之以「困」。困乎上者必反下，故受之以「井」。井道不可不革，故受之以「革」。革物者莫若鼎，故受之以「鼎」。主器者莫若長子，故受之「震」。「震」者，動也。物不可以終動，止之，故受之以「艮」。「艮」者，止也。物不可以終止，故受之以「漸」。「漸」者，進也。進必有所歸，故受之以「歸妹」。得其所歸者必大，故受之以「豐」。「豐」者，大也。窮大者必失其居，故受之以「旅」。旅而無所容，故受之以「巽」。「巽」者，入也。入而後說之，故受之以「兌」。「兌」者，說也。說而後散之，故受之以「渙」。渙者，離也。物不可以終離，故受之以節。節而信之，故受之以中孚。有其信者必行之，故受之以小過。有過物者必濟，故受之以既濟。物不可窮也，故受之以未濟終焉。雜卦 ​乾剛坤柔，比樂師憂。臨觀之義，或與或求。屯見而不失其居，蒙雜而著。震起也。艮止也。損益，盛衰之始也。大畜，時也。無妄，災也。萃聚，而升不來也。謙輕，而豫怠也。噬嗑，食也。賁，無色也。兌見，而巽伏也。隨，無故也。蠱則飾也。剝，爛也。復，反也。晉，晝也。明夷，誅也。井通，而困相遇也。鹹，速也。恆，久也。渙，離也。節，止也。解，緩也。蹇，難也。睽，外也。家人，內也。否，泰，反其類也。大壯則止，遁則退也。大有，眾也。同人，親也。革，去故也。鼎，取新也。小過，過也。中孚，信也。豐多故親寡，旅也。離上而坎下也。小畜，寡也。履，不處也。需，不進也。訟，不親也。大過，顛也。姤，遇也，柔遇剛也。漸，女歸待男行也。頤，養正也。既濟，定也。歸妹，女之終也。未濟，男之窮也。夬，決也，剛決柔也，君子道長，小人道憂也。周易經傳集解卷三十五，",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
